class Group:
    def __init__(self, members):
        self.members = list(members)
        self._balances = {m: 0.0 for m in self.members}
        self._expenses = []

    def add_expense(self, payer, amount, participants=None, description: str = ""):
        if amount <= 0:
            raise ValueError("Amount must be positive")
        if payer not in self._balances:
            raise ValueError(f"Payer {payer!r} is not a group member")

        if participants is None:
            participants = list(self.members)
        if not participants:
            raise ValueError("Participants list cannot be empty")
        for p in participants:
            if p not in self._balances:
                raise ValueError(f"Participant {p!r} is not a group member")

        # Convert to cents to avoid floating point issues
        total_cents = round(amount * 100)
        n = len(participants)

        # Split equally in cents; floor for each participant, remainder to payer
        base = total_cents // n

        # Each non-payer participant owes `base` cents (rounded down).
        # Payer covers the rest.
        non_payers = [p for p in participants if p != payer]

        owed_to_payer = 0
        for p in non_payers:
            self._balances[p] -= base / 100.0
            owed_to_payer += base
        self._balances[payer] += owed_to_payer / 100.0

        self._expenses.append({
            "payer": payer,
            "amount": amount,
            "participants": list(participants),
            "description": description,
        })

    def expenses(self) -> list[dict]:
        return [
            {
                "payer": e["payer"],
                "amount": e["amount"],
                "participants": list(e["participants"]),
                "description": e["description"],
            }
            for e in self._expenses
        ]

    def balances(self):
        return dict(self._balances)

    def settle_up(self):
        # Work in cents
        cents = {m: round(b * 100) for m, b in self._balances.items()}

        debtors = sorted(
            [(m, -c) for m, c in cents.items() if c < 0],
            key=lambda x: -x[1],
        )
        creditors = sorted(
            [(m, c) for m, c in cents.items() if c > 0],
            key=lambda x: -x[1],
        )

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            d_name, d_amt = debtors[i]
            c_name, c_amt = creditors[j]
            pay = min(d_amt, c_amt)
            if pay > 0:
                payments.append((d_name, c_name, pay / 100.0))
            d_amt -= pay
            c_amt -= pay
            if d_amt == 0:
                i += 1
            else:
                debtors[i] = (d_name, d_amt)
            if c_amt == 0:
                j += 1
            else:
                creditors[j] = (c_name, c_amt)

        # Filter out payments smaller than 1.00 (100 cents)
        result = []
        for debtor, creditor, amt in payments:
            cents_amt = round(amt * 100)
            if cents_amt >= 100:
                result.append((debtor, creditor, amt))
        return result

    def export_csv(self) -> str:
        import csv
        import io

        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(["payer", "amount", "participants", "description"])
        for e in self._expenses:
            writer.writerow([
                e["payer"],
                e["amount"],
                ";".join(e["participants"]),
                e["description"],
            ])
        return output.getvalue()
```

